package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.gui.components.Button;import net.minecraft.network.chat.Component;
/** Fixed logical layout scaled uniformly, including input coordinates, for small GUI resolutions. */
public final class AdcScreen extends Screen{
 private final AdcBlockEntity block;private float scale;private int x,y;private Button power,automatic;private final Button[]priority=new Button[3];private int ticks;private net.minecraft.client.gui.components.EditBox friend;
 public AdcScreen(AdcBlockEntity b){super(t("title"));block=b;}private static net.minecraft.network.chat.MutableComponent t(String k,Object...a){return Component.translatable("adc01."+k,a);}private void send(int a,int s){AddonNetwork.adcAction(new AdcAction(block.getBlockPos(),a,s));}
 private Button button(Component text,int px,int py,int w,Runnable action){var b=Button.builder(text,v->action.run()).bounds(px,py,w,18).build();addRenderableWidget(b);return b;}
 @Override protected void init(){scale=Math.min(1,Math.min((width-12)/360f,(height-12)/286f));x=Math.round((width/scale-360)/2);y=Math.round((height/scale-286)/2);power=button(t("power"),x+10,y+52,166,()->send(1,0));automatic=button(t("automatic"),x+184,y+52,166,()->send(2,0));var load=button(t("load"),x+10,y+92,166,()->send(3,0));load.setTooltip(net.minecraft.client.gui.components.Tooltip.create(Component.literal("Uses ").append(new net.minecraft.world.item.ItemStack(AdcBlockEntity.ammunition()).getHoverName()).append(" (superbwarfare:small_shell_aa)")));button(t("unload"),x+184,y+92,166,()->send(4,0));for(int i=0;i<3;i++){final int slot=i;priority[i]=button(t("category"+i),x+10+i*115,y+174,110,()->send(5,slot));}button(t("unlink"),x+10,y+260,166,()->send(6,0));button(Component.translatable("gui.done"),x+184,y+260,166,this::onClose);friend=new net.minecraft.client.gui.components.EditBox(font,x+10,y+212,340,18,Component.literal("Player name or UUID"));friend.setMaxLength(36);friend.setHint(Component.literal("Online player name or UUID"));addRenderableWidget(friend);button(Component.literal("Whitelist player"),x+10,y+236,166,()->AddonNetwork.adcAction(new AdcAction(block.getBlockPos(),7,0,friend.getValue())));button(Component.literal("Remove player"),x+184,y+236,166,()->AddonNetwork.adcAction(new AdcAction(block.getBlockPos(),8,0,friend.getValue())));send(0,0);tick();}
 @Override public void tick(){if(minecraft.player==null||block.isRemoved()||minecraft.player.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(block.getBlockPos()))>196){onClose();return;}if(++ticks%40==0)send(0,0);power.setMessage(t("power").append(": ").append(t(block.enabled?"on":"off")));automatic.setMessage(t("automatic").append(": ").append(t(block.automatic?"on":"off")));for(int i=0;i<3;i++)priority[i].setMessage(t("category"+i).append(": ").append(t("priority"+((block.priorities>>(i*2))&3))));}
 private void panel(GuiGraphics g){g.pose().pushPose();g.pose().scale(scale,scale,1);g.fill(x,y,x+360,y+286,0xf0182324);g.fill(x,y,x+360,y+3,0xffa4b888);g.drawString(font,title,x+10,y+10,0xe4eadf);var team=minecraft.level.getScoreboard().getPlayersTeam(block.ownerName);g.drawString(font,font.plainSubstrByWidth(t("owner",block.ownerName,team==null?"-":team.getName()).getString(),340),x+10,y+25,0xc6d1c2);g.drawString(font,t("status."+block.status),x+10,y+38,0xffd38a);g.drawString(font,t("ammo",block.count(),AdcConfig.CAPACITY.get()),x+10,y+78,0xcbd7c7);g.drawString(font,t("heat",Math.round(block.heat)),x+10,y+118,block.overheated?0xff7979:0xd2d9cd);g.fill(x+10,y+132,x+350,y+136,0xff3e4846);g.fill(x+10,y+132,x+10+(int)(340*block.heat/100),y+136,block.overheated?0xffda6464:0xffccba68);g.drawString(font,font.plainSubstrByWidth(t("target",block.targetName.isEmpty()?"-":block.targetName,Math.round(block.targetDistance)).getString(),340),x+10,y+144,0xcbd7c7);g.drawString(font,font.plainSubstrByWidth(t("radar",Component.translatable("defense.status."+block.radarState).getString(),block.radarId==null?"":"DR-01 #"+block.radarId.toString().substring(0,6)).getString(),340),x+10,y+158,0xcbd7c7);g.drawString(font,font.plainSubstrByWidth("Whitelist: "+String.join(", ",block.whitelist.values()),340),x+10,y+200,0xcbd7c7);g.pose().popPose();}
 @Override public void renderBackground(GuiGraphics g,int mx,int my,float dt){}@Override public void render(GuiGraphics g,int mx,int my,float dt){super.renderBackground(g,mx,my,dt);panel(g);g.pose().pushPose();g.pose().scale(scale,scale,1);super.render(g,(int)(mx/scale),(int)(my/scale),dt);g.pose().popPose();}
 @Override public boolean mouseClicked(double mx,double my,int button){return super.mouseClicked(mx/scale,my/scale,button);}@Override public boolean mouseReleased(double mx,double my,int button){return super.mouseReleased(mx/scale,my/scale,button);}@Override public boolean mouseDragged(double mx,double my,int button,double dx,double dy){return super.mouseDragged(mx/scale,my/scale,button,dx/scale,dy/scale);}@Override public boolean isPauseScreen(){return false;}
}
